for (const envelope of envelopes) {
  const taskId = String(envelope.taskId ?? ''); const actual = resultByTask.get(taskId);
  if (!taskId) { errors.push('task_id_required'); continue; }
  if (envelope.status !== 'ready_for_gateway') { collected.push({ taskId, status: envelope.status, reason: envelope.reason ?? null, executed: false, provider: envelope.selectedProvider ?? null, model: envelope.selectedModel ?? null, result: null }); continue; }
  if (!actual) { warnings.push('missing_execution_result:' + taskId); collected.push({ taskId, status: 'not_returned', reason: 'gateway_result_not_returned', executed: false, provider: envelope.selectedProvider ?? null, model: envelope.selectedModel ?? null, result: null }); continue; }
  collected.push({ taskId, status: normalizeStatus(actual.status), executed: actual.executed === true, provider: actual.providerId ?? actual.provider ?? envelope.selectedProvider ?? null, model: actual.model ?? envelope.selectedModel ?? null, tool: actual.tool ?? envelope.selectedTool ?? null, result: actual.result ?? actual.output ?? null, error: actual.error ?? null, timing: actual.timing ?? null, retryHistory: Array.isArray(actual.retryHistory) ? actual.retryHistory : [], fallbackHistory: Array.isArray(actual.fallbackHistory) ? actual.fallbackHistory : [] });
}
const completed = collected.filter(x => x.status === 'completed').length; const partial = collected.filter(x => x.status === 'partial').length; const failed = collected.filter(x => x.status === 'failed').length; const blocked = collected.filter(x => !['completed','partial','failed','cancelled'].includes(x.status)).length;
